    const sameName = main.replace(/\.obj$/i,'.mtl');
    const inferred = catalog.exact.get(sameName);
    if (inferred) { libraries = [basename(sameName)]; warnings.push('OBJ بلا mtllib: اكتُشف MTL مطابق لاسم الملف، وسيتم ربطه تلقائيًا.'); }
    else warnings.push('OBJ بلا مرجع mtllib؛ الخامات غير مضمونة. أعد تصدير النموذج مع MTL.');
