      try { img=findLocalFile(catalog,map.path,[dirname(found.path),mainDir]); }
      catch(e) {errors.push(e.message);continue;}
      if (!img) {errors.push(`خامة مفقودة (${map.slot} / ${map.material}): ${map.path}`);continue;}
      linkedTextures.add(img.path);
      if (img.match !== 'exact') warnings.push(`خامة ${map.path} طابقت مسارًا بديلًا؛ يفضّل تصحيح MTL.`);
      if (!EXT_BROWSER.test(img.path)) warnings.push('خامة بصيغة '+img.path.split('.').pop()+' قد تحتاج تحويلًا إلى PNG/JPEG/WebP قبل الاستيراد.');
