function __axPatchOptionalImages(json, missing){
 const copy=structuredClone(json);const bad=new Set(missing),textureIds=new Set();
 (copy.textures||[]).forEach((t,i)=>{if(bad.has(t?.source)||Object.values(t?.extensions||{}).some(v=>bad.has(v?.source)))textureIds.add(i);});
 function walk(o){if(!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o)){if(/Texture$/.test(k)&&typeof v?.index==='number'&&textureIds.has(v.index))delete o[k];else if(v&&typeof v==='object')walk(v);}}
 (copy.materials||[]).forEach(walk);return copy;
}
function __axRewriteGLB(buffer,json){
 const raw=new Uint8Array(buffer),v=new DataView(raw.buffer,raw.byteOffset,raw.byteLength);
 if(raw.length<20||v.getUint32(0,true)!==0x46546c67||v.getUint32(4,true)!==2)throw Error('GLB غير صالح');
 const chunks=[];for(let cur=12;cur<raw.length;){const len=v.getUint32(cur,true);if(cur+8+len>raw.length)throw Error('GLB مبتور');chunks.push({type:v.getUint32(cur+4,true),data:raw.slice(cur+8,cur+8+len)});cur+=8+len;}
 const encoded=new TextEncoder().encode(JSON.stringify(json)),padded=new Uint8Array(Math.ceil(encoded.length/4)*4);padded.fill(32);padded.set(encoded);chunks[0]={type:0x4e4f534a,data:padded};
 const total=12+chunks.reduce((n,c)=>n+8+c.data.length,0),out=new Uint8Array(total),d=new DataView(out.buffer);
 d.setUint32(0,0x46546c67,true);d.setUint32(4,2,true);d.setUint32(8,total,true);let offset=12;for(const c of chunks){d.setUint32(offset,c.data.length,true);d.setUint32(offset+4,c.type,true);out.set(c.data,offset+8);offset+=8+c.data.length;}return out.buffer;
}
function __axFilterMtl(source,catalog,library,base){
 const dirname=library.slice(0,library.lastIndexOf('/')+1),bad=[];
 const filtered=source.split(/\r?\n/).map(line=>{const m=/^\s*(map_kd|map_ka|map_ks|map_ke|map_d|map_pr|map_pm|map_bump|bump|norm|disp|decal|refl)\s+(.+)$/i.exec(line);if(!m)return line;
 let path=m[2].trim();path=path.replace(/^-(?:s|o|t)\s+(?:-?\d+(?:\.\d+)?\s*){1,3}/i,'').replace(/^-(?:bm|boost|texres|imfchan|type|clamp|blendu|blendv)\s+\S+\s*/i,'').trim().replace(/^['"]|['"]$/g,'');
 let ok=null;try{ok=__ayoubAssetCheck.findLocalFile(catalog,path,[dirname,base]);}catch{}if(ok)return line;bad.push(path);return '# omitted missing texture';});
 return {text:filtered.join('\n'),missing:bad};
}

